html.script:
function getSplunkSessionKey() {
  return splunkjs.mvc.createService().sessionKey || "";
}

function showMessage(text, isError) {
  var el = document.getElementById("message");
  el.textContent = text;
  el.style.display = "block";
  el.style.background = isError ? "#fde8e8" : "#e6f7e6";
  el.style.color = isError ? "#c62828" : "#2d7d2d";
  el.style.border = isError ? "1px solid #f5c6c6" : "1px solid #b8e6b8";
}

function loadConfig() {
  var service = splunkjs.mvc.createService();
  service.request(
    "/servicesNS/-/psexposed_app/storage/passwords",
    "GET",
    null,
    { output_mode: "json", count: 0 },
    null,
    null,
    function(err, response) {
      if (err || !response || !response.data) return;
      var entries = response.data.entry || [];
      var username = service.username || Splunk.util.getConfigValue("USERNAME");
      var realm = "psexposed__" + username;
      for (var i = 0; i < entries.length; i++) {
        if (entries[i].content && entries[i].content.realm === realm) {
          try {
            var config = JSON.parse(entries[i].content.clear_password);
            if (config.base_url) document.getElementById("base_url").value = config.base_url;
            if (config.api_key) {
              var key = config.api_key;
              var masked = key.length > 12 ? key.substring(0,8) + "****" + key.substring(key.length-4) : "****";
              document.getElementById("current-key-display").textContent = "Current key: " + masked;
              document.getElementById("status-container").innerHTML =
                'Configured';
            }
          } catch(e) {}
          return;
        }
      }
      document.getElementById("status-container").innerHTML =
        'Not Configured';
    }
  );
}

function saveConfig() {
  var apiKey = document.getElementById("api_key").value.trim();
  var baseUrl = document.getElementById("base_url").value.trim();
  if (!apiKey) { showMessage("Please enter your API key.", true); return; }

  var btn = document.getElementById("save-btn");
  btn.disabled = true;
  btn.textContent = "Saving...";

  var service = splunkjs.mvc.createService();
  var username = service.username || Splunk.util.getConfigValue("USERNAME");
  var realm = "psexposed__" + username;
  var configJson = JSON.stringify({ base_url: baseUrl, api_key: apiKey });

  // First check if entry exists
  service.request(
    "/servicesNS/nobody/psexposed_app/storage/passwords",
    "GET",
    null,
    { output_mode: "json", search: "realm=" + realm, count: 0 },
    null,
    null,
    function(err, response) {
      var entries = (response && response.data && response.data.entry) ? response.data.entry : [];
      if (entries.length > 0) {
        // Update existing
        var name = entries[0].name;
        // Extract just the ID portion for the URL
        var parts = name.split("/");
        var entryId = encodeURIComponent(parts[parts.length - 1]);
        service.request(
          "/servicesNS/nobody/psexposed_app/storage/passwords/" + entryId,
          "POST",
          null,
          null,
          { password: configJson },
          { "Content-Type": "application/x-www-form-urlencoded" },
          function(err2) {
            btn.disabled = false;
            btn.textContent = "Save Configuration";
            if (err2) { showMessage("Failed to update: " + (err2.data || err2.message || err2), true); }
            else { showMessage("Configuration saved successfully!", false); loadConfig(); document.getElementById("api_key").value = ""; }
          }
        );
      } else {
        // Create new
        service.request(
          "/servicesNS/nobody/psexposed_app/storage/passwords",
          "POST",
          null,
          null,
          { name: username, password: configJson, realm: realm },
          { "Content-Type": "application/x-www-form-urlencoded" },
          function(err2) {
            btn.disabled = false;
            btn.textContent = "Save Configuration";
            if (err2) { showMessage("Failed to save: " + (err2.data || err2.message || err2), true); }
            else { showMessage("Configuration saved successfully!", false); loadConfig(); document.getElementById("api_key").value = ""; }
          }
        );
      }
    }
  );
}

// Load on ready
require(["splunkjs/mvc", "splunkjs/mvc/simplexml/ready!"], function(mvc) {
  loadConfig();
});
